function resolveCorrection(id,reject){const r=rec('corrections',id);modal(reject?'Zamietnuť žiadosť':'Stiahnuť vlastnú žiadosť',`<p class="full">${E(r.data.reason)} · ${E(r.data.timeIn)}–${E(r.data.timeOut)}</p>${area('Dôvod rozhodnutia','reason','','required')}`,reject?'Zamietnuť':'Stiahnuť',v=>write({op:reject?'reject_correction':'withdraw_correction',kind:'corrections',id,version:r.version,reason:v.reason,data:r.data}));}
