function saleForm(id){const r=rec('sales',id),d=r?.data||{};modal(id?'Oprava tržby':'Denná uzávierka',`${field('Dátum','date',d.date||today(),'date','required max="'+today()+'"')}${field('Hotovostná tržba (€)','cash',d.cash??'','text','required inputmode="decimal"')}${field('Karty (€)','card',d.card??'','text','required inputmode="decimal"')}${field('Tringelty (€) · mimo tržby','tips',d.tips??0,'text','required inputmode="decimal"')}${field('Spočítaná hotovosť v pokladni (€)','cashCounted',d.cashCounted??'','text','required inputmode="decimal"')}${area('Poznámka k tržbe','note',d.note||'')}${area('Odkaz ďalšej zmene','handover',d.handover||'')}${id?area('Dôvod opravy','reason','','required'):''}<div class="full notice">Spočítaná hotovosť je samostatný údaj; obsahuje aj prípadný počiatočný vklad.<br><span id="closing-checklist"></span><br>Uloženie tržby samo nepotvrdzuje splnenie checklistu.</div>`,'Uložiť tržbu a odkaz',v=>save('sales',id,{...d,date:v.date,cash:number(v.cash),card:number(v.card),tips:number(v.tips),cashCounted:number(v.cashCounted),note:v.note,handover:v.handover,createdAt:d.createdAt||new Date().toISOString()},v.reason||'',r?.version||0));const selected=body.querySelector('[name=date]');const showChecks=()=>{const c=closingChecklist(records,selected.value);body.querySelector('#closing-checklist').textContent=`Večerné úlohy pre ${selected.value}: ${c.done}/${c.total}.${c.missing.length?' Nesplnené: '+c.missing.join(', '):c.total?' Všetky aktuálne schválené úlohy sú zaznamenané.':' Nie sú nastavené schválené večerné úlohy.'}`;};selected.addEventListener('change',showChecks);showChecks();}
function stockForm(id){const r=rec('stock',id),d=r?.data||{};modal('Skladová položka',`${field('Názov','name',d.name||'','text','required')}${select('Jednotka','unit',['g','kg','ml','l','ks'].map(x=>[x,x]),d.unit||'ks')}${field('Minimálna zásoba','minimum',d.minimum??0,'text','required inputmode="decimal"')}${field('Najbližší dátum spotreby · nepovinné','expiryDate',d.expiryDate||'','date')}${field('Upozorniť vopred (dní)','expiryWarningDays',d.expiryWarningDays??3,'number','min="0" max="90" required')}${field('Cena za 1 skladovú jednotku (€) · nepovinné','unitCost',d.unitCost??'','text','inputmode="decimal"')}`,'Uložiť',v=>save('stock',id,{...d,...v,expiryWarningDays:number(v.expiryWarningDays),minimum:number(v.minimum),unitCost:v.unitCost===''?null:number(v.unitCost)},'',r?.version||0));}
