function settingsForm(){const r=rec('settings','main'),s=r.data,days=['Nedeľa','Pondelok','Utorok','Streda','Štvrtok','Piatok','Sobota'];modal('Prevádzkové pravidlá',`${field('Počet ľudí súčasne na zmene','capacity',s.capacity||1,'number','required min="1" max="20"')}<p class="full muted">Prázdne oba časy znamenajú zatvorené. Časy nižšie sú prevzaté z pôvodnej aplikácie.</p>${days.map((day,i)=>field(day+' od','start'+i,s.hours?.[i]?.[0]||'','time')+field(day+' do','end'+i,s.hours?.[i]?.[1]||'','time')).join('')}<label class="checklabel full"><input name="confirmed" type="checkbox" required> Potvrdzujem, že toto sú platné časy a kapacita prevádzky.</label>`,'Potvrdiť a uložiť',v=>{const hh={};for(let i=0;i<7;i++){if(v['start'+i]||v['end'+i]){if(!v['start'+i]||!v['end'+i])throw Error('Doplň oba časy alebo oba vymaž.');hh[i]=[v['start'+i],v['end'+i]];}}return save('settings','main',{...s,hours:hh,capacity:number(v.capacity),scheduleConfirmed:true},'',r.version);});}
function personForm(id){const p=person(id)||{},expectedPerson=p.id?Object.fromEntries(['id','name','avatar','user_id','role','active'].map(key=>[key,p[key]])):null;modal('Profil a prístup',`${field('Meno','name',p.name||'','text','required')}${field('Overený e-mail účtu · prázdne ponechá priradenie','email','','email')}${select('Rola','role',[['employee','Zamestnanec'],['admin','Administrátor']],p.role||'employee')}${select('Avatar','avatar',[['pudlik','Pudlík'],['zaba','Žaba'],['kuriatko','Kuriatko'],['macicka','Mačička'],['medvedik','Medvedík'],['tucniak','Tučniak'],['zirafa','Žirafa']],p.avatar||'pudlik')}${select('Profil','active',[['true','Aktívny'],['false','Neaktívny']],String(p.active??true))}${area('Dôvod zmeny prístupu','reason')}`,'Uložiť profil',v=>write({op:'person',id:id||crypto.randomUUID(),expectedPerson,reason:v.reason,data:{...v,active:v.active==='true'}}));}
